/** Top players per category for one division. */
const POTM_POINTS = 3;
function computeFootballStats(matches) {
  const players = new Map();
  for (const m of matches) {
    const potm = m.status === 'COMPLETED' && m.potm ? m.potm.id : null;
    for (const r of m.player_stats || []) {
      const k = `${m.division_id}:${r.id}`;
      if (!players.has(k)) players.set(k, { division_id: m.division_id, member_id: r.id, name: r.name, entry_id: r.team,
        goals: 0, assists: 0, yellow: 0, red: 0, clean_sheets: 0, potm: 0, points: 0 });
      const p = players.get(k);
      p.goals += r.goals || 0; p.assists += r.assists || 0; p.yellow += r.yellow || 0; p.red += r.red || 0;
      p.clean_sheets += r.clean_sheet || 0; p.points += r.points || 0;
      if (potm === r.id) { p.potm++; p.points += POTM_POINTS; }
    }
