// Matches counted: period and ball.
const day = 864e5, now = Date.now();
const from = f.period === 'YEAR' ? `${new Date().getFullYear()}-01-01` : f.period === '90D' ? new Date(now - 90 * day).toISOString().slice(0, 10) : '';
